// Signed approve/deny links: HMAC over crId + decision with PACT_APPROVAL_SECRET (generated by infra/sandbox/agent.sh,
// known only to the agent), so a link can't be forged or edited into a different CR or decision.
import { createHmac, timingSafeEqual } from 'node:crypto';

export type Decision = 'approve' | 'deny';
const secret = () => {
  const s = process.env.PACT_APPROVAL_SECRET;
  if (!s) throw new Error('PACT_APPROVAL_SECRET is not set');
  return s;
};
export const approvalToken = (crId: string, d: Decision) =>
  createHmac('sha256', secret()).update(`${crId}:${d}`).digest('base64url');
export function validToken(crId: string, d: string, token: string) {
  if (d !== 'approve' && d !== 'deny') return false;
  const want = Buffer.from(approvalToken(crId, d)), got = Buffer.from(token);
  return want.length === got.length && timingSafeEqual(want, got);
}
export const approvalLink = (crId: string, d: Decision) =>
  `${process.env.PACT_APPROVAL_URL ?? 'http://localhost:4000'}/approval/${encodeURIComponent(crId)}?d=${d}&t=${approvalToken(crId, d)}`;
